def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    idx = {c: i for i, c in enumerate(alphabet)}
    k = len(alphabet)
    nxt = [[-1] * k]
    out = [False]
    seen = set()
    for w in banned:
        if not w or w in seen:
            continue
        seen.add(w)
        u = 0
        for ch in w:
            c = idx[ch]
            if nxt[u][c] < 0:
                nxt[u][c] = len(nxt)
                nxt.append([-1] * k)
                out.append(False)
            u = nxt[u][c]
        out[u] = True
    m_nodes = len(nxt)
    fail = [0] * m_nodes
    from collections import deque
    q = deque()
    for c in range(k):
        v = nxt[0][c]
        if v >= 0:
            fail[v] = 0
            q.append(v)
        else:
            nxt[0][c] = 0
    while q:
        u = q.popleft()
        for c in range(k):
            v = nxt[u][c]
            if v >= 0:
                f = nxt[fail[u]][c]
                fail[v] = f
                if out[f]:
                    out[v] = True
                q.append(v)
            else:
                nxt[u][c] = nxt[fail[u]][c]
    good = [s for s in range(m_nodes) if not out[s]]
    if 0 not in good:
        return 0
    gid = {s: i for i, s in enumerate(good)}
    m = len(good)
    mat = [[0] * m for _ in range(m)]
    for s in good:
        i = gid[s]
        row = mat[i]
        for c in range(k):
            t = nxt[s][c]
            j = gid.get(t)
            if j is not None:
                row[j] += 1
    def mul(a, b):
        c = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ci = c[i]
            for t in range(m):
                aik = ai[t]
                if not aik:
                    continue
                bt = b[t]
                for j in range(m):
                    ci[j] = (ci[j] + aik * bt[j]) % MOD
        return c
    res = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    base = mat
    e = n
    while e:
        if e & 1:
            res = mul(res, base)
        base = mul(base, base)
        e >>= 1
    start = gid[0]
    return sum(res[start]) % MOD
